344	#[cfg(test)]
345	mod tests {
346	    use super::*;
347	    use paigasus_helikon_core::ContentPart;
348	    use serde_json::json;
349	
350	    fn text(t: &str) -> ContentPart {
351	        ContentPart::Text { text: t.to_owned() }
352	    }
353	
354	    fn user(content: Vec<ContentPart>) -> Item {
355	        Item::UserMessage { content }
356	    }
357	
358	    fn assistant(content: Vec<ContentPart>) -> Item {
359	        Item::AssistantMessage {
360	            content,
361	            agent: None,
362	        }
363	    }
364	
365	    fn system(t: &str) -> Item {
366	        Item::System {
367	            content: vec![text(t)],
368	        }
369	    }
370	
371	    // Helper: parse the wire projection for assertions.
372	    fn wire(items: &[Item]) -> Result<Value, ModelError> {
373	        let tm = items_to_messages(items)?;
374	        Ok(messages_to_wire_json(&tm))
375	    }
376	
377	    #[test]
378	    fn empty_conversation_returns_error() {
379	        let err = items_to_messages(&[]).unwrap_err();
380	        assert!(matches!(err, ModelError::Other(_)));
381	    }
382	
383	    #[test]
384	    fn system_only_returns_error() {
385	        // System items don't count as messages.
386	        let items = vec![system("be helpful")];
387	        let err = items_to_messages(&items).unwrap_err();
388	        assert!(matches!(err, ModelError::Other(_)));
389	    }
