419	    #[test]
420	    fn tool_call_item_queues_onto_assistant_turn() {
421	        let items = vec![Item::ToolCall {
422	            call_id: "tu_1".to_owned(),
423	            name: "ping".to_owned(),
424	            args: json!({"host": "example.com"}),
425	        }];
426	        let w = wire(&items).unwrap();
427	        // ToolCall flushes as an assistant turn; leading-assistant rule kicks in.
428	        let msgs = w["messages"].as_array().unwrap();
429	        assert_eq!(msgs.len(), 2); // synthetic user + assistant
430	        let assistant_msg = &msgs[1];
431	        assert_eq!(assistant_msg["role"], "assistant");
432	        assert_eq!(assistant_msg["content"][0]["type"], "tool_use");
433	        assert_eq!(assistant_msg["content"][0]["toolUseId"], "tu_1");
434	    }
