436	    #[test]
437	    fn tool_result_item_queues_onto_user_turn() {
438	        let items = vec![
439	            user(vec![text("call ping")]),
440	            assistant(vec![ContentPart::ToolUse {
441	                call_id: "tu_1".to_owned(),
442	                name: "ping".to_owned(),
443	                args: json!({}),
444	            }]),
445	            Item::ToolResult {
446	                call_id: "tu_1".to_owned(),
447	                content: vec![text("pong")],
