462	        let items = vec![
463	            user(vec![text("call ping")]),
464	            assistant(vec![ContentPart::ToolUse {
465	                call_id: "tu_1".to_owned(),
466	                name: "ping".to_owned(),
467	                args: json!({}),
468	            }]),
469	            Item::ToolResult {
470	                call_id: "tu_1".to_owned(),
471	                content: vec![text("pong")],
472	            },
473	            user(vec![text("now what?")]),
474	        ];
475	        let w = wire(&items).unwrap();
